-- NEW_FILE: Catalog/NumberTheory/AbundancyIndex.lean
/-
  # The Abundancy Index σ(n)/n and the Structure of Odd Perfect Numbers

  Category (Menu Balance): **bridge across catalog domains.**
  This file bridges three strands: the multiplicative `ArithmeticFunction.sigma`
  machinery, Mathlib's abundant/deficient classification
  (`Nat.Abundant` / `Nat.Deficient`), and the *perfect number* theory developed in
  `EuclidEuler.lean`.  The unifying object is the **abundancy index**
  `I(n) = σ(n)/n : ℚ`, a multiplicative function with `I(n) = 2 ⇔ n` perfect.

  The classification of *even* perfect numbers is complete (Euclid–Euler).  For
  *odd* perfect numbers nothing is known to exist; the research frontier (Nielsen)
  forces ≥ 101 prime factors.  That deep bound is out of reach here, but the
  abundancy framework yields the classical, fully-proved structural facts:

  Main results:
  * `abundancy_perfect_iff` — `I(n) = 2 ↔ Perfect n` (for `0 < n`).
  * `abundancy_eq_mul_of_coprime` — `I` is multiplicative on coprime arguments.
  * `sigma_one_lt_prime_pow_bound` — `σ(p^k) · (p-1) < p^(k+1)` (sharp prime-power
    estimate underlying `I(p^k) < p/(p-1)`).
  * `not_perfect_prime_pow` — **no prime power is perfect** (hence every perfect
    number has ≥ 2 distinct prime factors).
  * `perfect_two_le_card_primeFactors` — any perfect `n > 1` has ≥ 2 distinct primes.
  * `odd_perfect_three_le_card_primeFactors` — **every odd perfect number has at
    least 3 distinct prime factors** (the elementary precursor to Nielsen's 101).

  -- !-- Lab Notes -- !--
  HYPOTHESIS (PI): the abundancy index is multiplicative, so the abundancy of a
  number with few prime factors is a bounded product of prime-power abundancies,
  each `< p/(p-1)`; for odd primes this product stays below 2, ruling out small odd
  perfect numbers.
  EXPERIMENT (Experimenter): work in ℚ; prove `I(p^k) < p/(p-1)` from the ℕ
  identity `σ(p^k)(p-1) = p^(k+1) - 1 < p^(k+1)`.  For ≤ 2 distinct odd primes,
  bound `I(n) ≤ (3/2)(5/4) = 15/8 < 2`.
  ANALYSIS (Analyst): `not_perfect_prime_pow` falls out of the ℕ identity
  `p^k(p-2) + 1 ≠ 0`, needing no ℚ at all — a cleaner route than abundancy for the
  2-prime bound.  The 3-prime bound genuinely needs the abundancy product estimate
  and the fact that the two smallest odd primes are 3 and 5.
  CRITIQUE (Critic): the odd hypothesis is load-bearing for the 3-prime bound (an
  even perfect number `6 = 2·3` has only 2 primes); all results carry honest `0<n`
  / oddness / `1<n` hypotheses; 0 sorries.  We do NOT claim Nielsen's bound — the
  honest gap (3 vs 101) is documented in FUTURE_DIRECTIONS.md.
  SYNTHESIS (PI): the abundancy index is the right invariant; the same product
  estimate, pushed harder with quantitative prime gaps, is the engine behind the
  modern record bounds.
-/
import Mathlib

open Nat ArithmeticFunction Finset

namespace AbundancyIndex

local notation "σ₁" => ArithmeticFunction.sigma 1

/-- The **abundancy index** `I(n) = σ(n)/n` as a rational number. -/
noncomputable def abundancy (n : ℕ) : ℚ := (σ₁ n : ℚ) / (n : ℚ)

/-- `n` is perfect iff its abundancy index equals `2`. -/
theorem abundancy_perfect_iff {n : ℕ} (hn : 0 < n) :
    abundancy n = 2 ↔ Nat.Perfect n := by
  unfold abundancy; rw [ div_eq_iff ] <;> norm_cast;
  · simp +decide [ ArithmeticFunction.sigma, Nat.Perfect ];
    rw [ Nat.sum_divisors_eq_sum_properDivisors_add_self, two_mul, add_comm ] ; aesop;
  · grind

/-- The abundancy index is multiplicative on coprime arguments. -/
theorem abundancy_eq_mul_of_coprime {m n : ℕ} (h : Nat.Coprime m n) :
    abundancy (m * n) = abundancy m * abundancy n := by
  by_cases hm : m = 0 <;> by_cases hn : n = 0 <;> simp_all +decide [ abundancy ];
  convert congr_arg ( fun x : ℕ => ( x : ℚ ) / ( m * n ) ) ( ArithmeticFunction.isMultiplicative_sigma.map_mul_of_coprime h ) using 1 ; push_cast ; ring!;

/-- Sharp prime-power estimate: `σ(p^k)·(p-1) < p^(k+1)`. -/
theorem sigma_one_lt_prime_pow_bound {p : ℕ} (hp : p.Prime) (k : ℕ) :
    σ₁ (p ^ k) * (p - 1) < p ^ (k + 1) := by
  rcases p with ( _ | _ | p ) <;> simp_all +decide [ ArithmeticFunction.sigma ];
  nlinarith [ geom_sum_mul_neg ( p + 1 + 1 : ℤ ) ( k + 1 ) ]

/-- **No prime power is perfect.** -/
theorem not_perfect_prime_pow {p : ℕ} (hp : p.Prime) {k : ℕ} :
    ¬ Nat.Perfect (p ^ k) := by
  rw [ Nat.Perfect ];
  rw [ Nat.properDivisors_prime_pow hp ] ; norm_num;
  exact fun h => absurd h ( by nlinarith [ hp.two_le, pow_pos hp.pos k, geom_sum_mul_neg ( p : ℤ ) k ] )

/-- Every perfect number greater than `1` has at least two distinct prime factors. -/
theorem perfect_two_le_card_primeFactors {n : ℕ} (hperf : Nat.Perfect n)
    (hn : 1 < n) : 2 ≤ n.primeFactors.card := by
  -- Assume n is a prime power, so there exists a prime p and k ≥ 1 such that n = p^k.
  by_contra h_contra
  obtain ⟨p, k, hp, hk, rfl⟩ : ∃ p k : ℕ, Nat.Prime p ∧ 0 < k ∧ n = p ^ k := by
    interval_cases _ : Finset.card n.primeFactors;
    · aesop;
    · rw [ Finset.card_eq_one ] at *;
      rcases ‹∃ a, n.primeFactors = { a } › with ⟨ p, hp ⟩ ; exact ⟨ p, n.factorization p, Nat.prime_of_mem_primeFactors <| hp.symm ▸ Finset.mem_singleton_self _, pos_iff_ne_zero.mpr <| Finsupp.mem_support_iff.mp <| by aesop, by nth_rw 1 [ ← Nat.factorization_prod_pow_eq_self hn.ne_bot ] ; rw [ Finsupp.prod ] ; aesop ⟩ ;
  exact not_perfect_prime_pow hp hperf

/-- Abundancy of a prime power is `< p/(p-1)`. -/
theorem abundancy_prime_pow_lt {p : ℕ} (hp : p.Prime) (k : ℕ) :
    abundancy (p ^ k) < (p : ℚ) / (p - 1) := by
  rcases p with ( _ | _ | p ) <;> simp_all +decide [ abundancy ];
  rw [ div_lt_div_iff₀ ] <;> norm_cast;
  · convert sigma_one_lt_prime_pow_bound hp k using 1 ; ring;
  · positivity;
  · grind

/-- **Every odd perfect number has at least three distinct prime factors.**
This is the elementary precursor to the modern record lower bounds (Nielsen's
≥ 101). The hypothesis `Odd n` is essential: the even perfect number `6 = 2·3`
has only two prime factors. -/
theorem odd_perfect_three_le_card_primeFactors {n : ℕ} (hperf : Nat.Perfect n)
    (hodd : Odd n) : 3 ≤ n.primeFactors.card := by
  by_contra! h_contra;
  -- Let $n$ be an odd perfect number with exactly two distinct prime factors $p$ and $q$.
  -- Then $n = p^a q^b$ for some positive integers $a$ and $b$.
  obtain ⟨p, q, a, b, hpq, hn⟩ : ∃ p q a b : ℕ, p.Prime ∧ q.Prime ∧ p ≠ q ∧ a > 0 ∧ b > 0 ∧ n = p^a * q^b := by
    interval_cases _ : #n.primeFactors;
    · cases n <;> simp_all +decide [ Nat.Perfect ];
    · -- If $n$ has exactly one prime factor $p$, then $n = p^a$ for some positive integer $a$.
      obtain ⟨p, a, hp, ha⟩ : ∃ p a : ℕ, p.Prime ∧ a > 0 ∧ n = p^a := by
        rw [ Finset.card_eq_one ] at *;
        rcases ‹∃ a, n.primeFactors = { a } › with ⟨ p, hp ⟩ ; rw [ Finset.eq_singleton_iff_unique_mem ] at hp; use p, n.factorization p; simp_all +decide ;
        exact ⟨ Nat.pos_of_ne_zero ( Finsupp.mem_support_iff.mp ( by aesop ) ), by nth_rw 1 [ ← Nat.factorization_prod_pow_eq_self hp.1.2.2 ] ; exact Finset.prod_eq_single p ( by aesop ) ( by aesop ) ⟩;
      exact absurd ( not_perfect_prime_pow hp ) ( by aesop );
    · rw [ Finset.card_eq_two ] at *;
      rcases ‹∃ x y : ℕ, x ≠ y ∧ n.primeFactors = { x, y } › with ⟨ p, q, hpq, h ⟩ ; use p, q, n.factorization p, n.factorization q ; simp_all +decide;
      exact ⟨ Nat.prime_of_mem_primeFactors ( h.symm ▸ Finset.mem_insert_self _ _ ), Nat.prime_of_mem_primeFactors ( h.symm ▸ Finset.mem_insert_of_mem ( Finset.mem_singleton_self _ ) ), Nat.pos_of_ne_zero ( Finsupp.mem_support_iff.mp ( by simp +decide [ h ] ) ), Nat.pos_of_ne_zero ( Finsupp.mem_support_iff.mp ( by simp +decide [ h ] ) ), by nth_rw 1 [ ← Nat.factorization_prod_pow_eq_self hodd.pos.ne' ] ; rw [ Finsupp.prod ] ; aesop ⟩;
  -- Using the multiplicative property of the abundancy index, we have $I(n) = I(p^a) \cdot I(q^b)$.
  have h_abundancy : (abundancy n) = (abundancy (p ^ a)) * (abundancy (q ^ b)) := by
    rw [ hn.2.2.2.2, abundancy_eq_mul_of_coprime ];
    exact Nat.coprime_pow_primes _ _ hpq hn.1 hn.2.1;
  -- Since $p$ and $q$ are distinct primes and $n$ is odd, we have $p \geq 3$ and $q \geq 5$.
  have hp_ge_3 : 3 ≤ p := by
    contrapose! hodd; interval_cases p <;> simp_all +decide [ parity_simps ] ;
    aesop
  have hq_ge_5 : 5 ≤ q ∨ 3 ≤ q ∧ q < 5 ∧ p ≥ 5 := by
    rcases q with ( _ | _ | _ | _ | _ | q ) <;> simp_all +arith +decide;
    · grind;
    · exact le_of_not_gt fun h => hn.1 <| by interval_cases p <;> trivial;
  -- Using the inequality $I(p^a) < \frac{p}{p-1}$ and $I(q^b) < \frac{q}{q-1}$, we get $I(n) < \frac{p}{p-1} \cdot \frac{q}{q-1}$.
  have h_abundancy_lt : (abundancy n) < (p : ℚ) / (p - 1) * (q : ℚ) / (q - 1) := by
    have h_abundancy_lt : (abundancy (p ^ a)) < (p : ℚ) / (p - 1) ∧ (abundancy (q ^ b)) < (q : ℚ) / (q - 1) := by
      exact ⟨ abundancy_prime_pow_lt hpq a, abundancy_prime_pow_lt hn.1 b ⟩;
    simpa only [ h_abundancy, mul_div_assoc ] using mul_lt_mul'' h_abundancy_lt.1 h_abundancy_lt.2 ( by exact div_nonneg ( Nat.cast_nonneg _ ) ( Nat.cast_nonneg _ ) ) ( by exact div_nonneg ( Nat.cast_nonneg _ ) ( Nat.cast_nonneg _ ) );
  -- Since $n$ is perfect, we have $I(n) = 2$.
  have h_abundancy_eq_2 : (abundancy n) = 2 := by
    exact abundancy_perfect_iff ( Nat.pos_of_ne_zero ( by aesop_cat ) ) |>.2 hperf;
  rcases hq_ge_5 with ( hq_ge_5 | ⟨ hq_ge_3, hq_lt_5, hp_ge_5 ⟩ ) <;> simp_all +decide [ div_mul_eq_mul_div ];
  · rw [ div_div, lt_div_iff₀ ] at h_abundancy_lt <;> nlinarith only [ show ( p : ℚ ) ≥ 3 by norm_cast, show ( q : ℚ ) ≥ 5 by norm_cast, h_abundancy_lt ];
  · interval_cases q <;> norm_num at *;
    rw [ div_div, lt_div_iff₀ ] at h_abundancy_lt <;> nlinarith only [ show ( p : ℚ ) ≥ 5 by norm_cast, h_abundancy_lt ]

end AbundancyIndex


