/-
  # Euclid–Euler Theorem: The Structure of Even Perfect Numbers

  Category (Menu Balance): **subtask of a famous open problem.**
  The Euclid–Euler theorem reduces the classification of *even* perfect numbers to
  the existence of Mersenne primes `2^p - 1`.  Whether there are infinitely many
  even perfect numbers is equivalent to whether there are infinitely many Mersenne
  primes — a long-standing open problem.  This file formalizes the exact
  biconditional underlying that reduction, which is **not present** in the pinned
  Mathlib version (the `Nat.Perfect` predicate and `mersenne` exist, but the
  classification theorem does not).

  Main results:
  * `sigma_one_two_pow` — `σ₁(2^k) = 2^(k+1) - 1 = mersenne (k+1)`.
  * `sigma_one_prime` — `σ₁(p) = p + 1` for a prime `p`.
  * `perfect_two_pow_mul_mersenne_of_prime` — **Euclid's direction**: if
    `mersenne (k+1)` is prime then `2^k * mersenne (k+1)` is perfect.
  * `eq_two_pow_mul_prime_mersenne_of_even_perfect` — **Euler's direction**: every
    even perfect number has the form `2^k * q` with `q = mersenne (k+1)` prime.
  * `even_perfect_iff_mersenne` — the Euclid–Euler biconditional.

  -- !-- Lab Notes -- !--
  HYPOTHESIS (PI): the multiplicativity of `σ₁` plus the geometric-sum value
  `σ₁(2^k) = 2^(k+1)-1` should give Euclid's direction directly, and a careful
  factorization argument on `σ₁(2^k · m) = 2 · 2^k · m` should force `m` to be a
  Mersenne prime for Euler's direction.
  EXPERIMENT (Experimenter): formalize `σ₁` via `ArithmeticFunction.sigma 1`; use
  `IsMultiplicative.map_mul_of_coprime` for the coprime split `2^k ⟂ (odd m)`.
  ANALYSIS (Analyst): the geometric sum `∑ i ∈ divisors (2^k), i` collapses with
  `Nat.sigma`/`Nat.geomSum_eq`; Euler's direction needs the key divisor identity
  that `m` and `σ₁(m) - m` are *complementary* divisors summing to `σ₁(m)`, which
  forces `σ₁(m) - m = 1`, i.e. `m` prime.
  CRITIQUE (Critic): all theorems carry honest positivity / primality hypotheses;
  the `mersenne 0 = 0` junk case is excluded by indexing with `k+1`; 0 sorries.
  SYNTHESIS (PI): the biconditional `even_perfect_iff_mersenne` packages both
  directions and is the precise statement whose "infinitely often" version is open.
-/
import Mathlib

open Nat ArithmeticFunction Finset

namespace EuclidEuler

/-- `σ₁` denotes the sum-of-divisors arithmetic function. -/
local notation "σ₁" => ArithmeticFunction.sigma 1

/-- The sum of divisors of `2^k` is the Mersenne number `2^(k+1) - 1`. -/
theorem sigma_one_two_pow (k : ℕ) : σ₁ (2 ^ k) = mersenne (k + 1) := by
  unfold mersenne;
  simp +decide [ ArithmeticFunction.sigma, Nat.geomSum_eq ]

/-- For a prime `p`, the sum of its divisors is `p + 1`. -/
theorem sigma_one_prime {p : ℕ} (hp : p.Prime) : σ₁ p = p + 1 := by
  rw [ ArithmeticFunction.sigma_apply, hp.sum_divisors ];
  grind

/-- **Euclid's direction.** If `mersenne (k+1) = 2^(k+1) - 1` is prime, then
`2^k * mersenne (k+1)` is a perfect number. -/
theorem perfect_two_pow_mul_mersenne_of_prime (k : ℕ)
    (hp : (mersenne (k + 1)).Prime) :
    Nat.Perfect (2 ^ k * mersenne (k + 1)) := by
  -- By definition of perfect numbers, we need to show that the sum of the proper divisors of `n` equals `n`.
  have h_sum_divisors : ∑ d ∈ (Nat.properDivisors (2 ^ k * mersenne (k + 1))), d = 2 ^ k * mersenne (k + 1) := by
    -- The sum of the divisors of $n = 2^k \cdot mersenne(k+1)$ is given by $\sigma(n) = \sigma(2^k) \cdot \sigma(mersenne(k+1))$.
    have h_sigma : ∑ d ∈ Nat.divisors (2 ^ k * mersenne (k + 1)), d = (mersenne (k + 1)) * ((mersenne (k + 1)) + 1) := by
      -- The divisors of $2^k \cdot mersenne(k+1)$ are $1, 2, 2^2, \ldots, 2^k, mersenne(k+1), 2 \cdot mersenne(k+1), \ldots, 2^k \cdot mersenne(k+1)$.
      have h_divisors : Nat.divisors (2 ^ k * mersenne (k + 1)) = Finset.image (fun i => 2 ^ i) (Finset.range (k + 1)) ∪ Finset.image (fun i => 2 ^ i * mersenne (k + 1)) (Finset.range (k + 1)) := by
        rw [ Nat.divisors_mul, Nat.divisors_prime_pow ] <;> norm_num [ hp ];
        rw [ hp.divisors ] ; ext; simp +decide [ Finset.mem_mul ] ; aesop;
      rw [ h_divisors, Finset.sum_union ];
      · rw [ Finset.sum_image <| by intros a ha b hb hab; simpa using Nat.pow_right_injective ( by decide ) hab, Finset.sum_image <| by intros a ha b hb hab; simpa using Nat.pow_right_injective ( by decide ) <| mul_right_cancel₀ hp.ne_zero hab ] ; simp +decide [ Finset.sum_range_succ', mersenne ] ; ring;
        norm_num [ ← Finset.mul_sum _ _ _, ← Finset.sum_mul ];
        nlinarith [ Nat.sub_add_cancel ( show 1 ≤ 2 ^ k * 2 from Nat.one_le_iff_ne_zero.mpr <| by positivity ), geom_sum_mul_neg ( 2 : ℤ ) k ];
      · norm_num [ Finset.disjoint_right ];
        intro a ha x hx H; have := congr_arg ( ·.factorization ( 2 : ℕ ) ) H; norm_num at this;
        rw [ Nat.factorization_mul ] at this <;> norm_num at *;
        · rw [ Nat.factorization_eq_zero_of_not_dvd ] at this <;> simp_all +decide [ Nat.Prime.dvd_iff_not_coprime ];
        · exact hp.ne_zero;
    grind +suggestions;
  simp_all +decide [ Nat.Perfect ]

/-- **Euler's direction.** Every even perfect number has the shape
`2^k * q`, where `q = mersenne (k+1)` is a (Mersenne) prime. -/
theorem eq_two_pow_mul_prime_mersenne_of_even_perfect {n : ℕ}
    (hperf : Nat.Perfect n) (heven : Even n) :
    ∃ k p, p.Prime ∧ p = mersenne (k + 1) ∧ n = 2 ^ k * p := by
  -- Let $k = n.factorization 2 \geq 1$ and $m = n / 2^k$ odd.
  obtain ⟨k, m, hk, hm⟩ : ∃ k m, 0 < k ∧ Odd m ∧ n = 2^k * m ∧ Nat.gcd (2^k) m = 1 := by
    use Nat.factorization n 2, n / 2^Nat.factorization n 2;
    refine' ⟨ Nat.pos_of_ne_zero _, _, Eq.symm ( Nat.mul_div_cancel' ( Nat.ordProj_dvd _ _ ) ), _ ⟩;
    · simp_all +decide [ even_iff_two_dvd, Nat.factorization_eq_zero_iff ];
      rintro rfl; simp_all +decide [ Nat.Perfect ];
    · exact Nat.odd_iff.mpr ( Nat.mod_two_ne_zero.mp fun h => absurd ( Nat.dvd_of_mod_eq_zero h ) ( Nat.not_dvd_ordCompl ( by norm_num ) ( by rintro rfl; simp_all +decide [ Nat.Perfect ] ) ) );
    · exact Nat.Coprime.pow_left _ ( Nat.prime_two.coprime_iff_not_dvd.mpr <| Nat.not_dvd_ordCompl ( by norm_num ) <| by rintro rfl; simp_all +decide [ Nat.Perfect ] );
  -- By multiplicativity of σ₁ (isMultiplicative_sigma, map_mul_of_coprime), σ₁(n) = σ₁(2^k) * σ₁(m) = (2^(k+1)-1) * σ₁(m). Also 2n = 2^(k+1) * m.
  have h_sigma : (mersenne (k + 1)) * (ArithmeticFunction.sigma 1 m) = (mersenne (k + 1) + 1) * m := by
    have h_sigma : (ArithmeticFunction.sigma 1 n) = (ArithmeticFunction.sigma 1 (2^k)) * (ArithmeticFunction.sigma 1 m) := by
      convert ArithmeticFunction.isMultiplicative_sigma.map_mul_of_coprime hm.2.2 using 1 ; aesop;
    simp_all +decide [ Nat.Perfect ];
    simp_all +decide [ ArithmeticFunction.sigma, mersenne ];
    simp_all +decide [ Nat.geomSum_eq ];
    simp_all +decide [ Nat.sum_divisors_eq_sum_properDivisors_add_self, pow_succ' ] ; linarith;
  -- Let $d = \sigma_1(m) - m$. Then $m = q * d$ and $\sigma_1(m) = m + d = (q+1) * d$.
  obtain ⟨d, hd⟩ : ∃ d, m = mersenne (k + 1) * d ∧ (ArithmeticFunction.sigma 1 m) = (mersenne (k + 1) + 1) * d := by
    -- Since $mersenne (k + 1)$ divides $(mersenne (k + 1) + 1) * m$, it must also divide $m$.
    have h_div : mersenne (k + 1) ∣ m := by
      exact ⟨ ( sigma 1 ) m - m, by rw [ mul_tsub ] ; exact eq_tsub_of_add_eq <| by linarith ⟩;
    exact Exists.elim h_div fun d hd => ⟨ d, hd, by nlinarith [ show 0 < mersenne ( k + 1 ) from Nat.sub_pos_of_lt ( one_lt_pow₀ one_lt_two ( by linarith ) ) ] ⟩;
  -- If $d > 1$, then $m$ has divisors $1$, $d$, and $m$ all distinct (since $q = 2^{k+1}-1 \geq 3$ as $k \geq 1$), giving $\sigma_1(m) \geq 1 + d + m > m + d$, contradiction.
  by_cases hd_gt_one : d > 1;
  · have h_contradiction : (ArithmeticFunction.sigma 1 m) ≥ 1 + d + m := by
      have h_contradiction : (ArithmeticFunction.sigma 1 m) ≥ ∑ x ∈ ({1, d, m} : Finset ℕ), x := by
        refine' le_trans _ ( Finset.sum_le_sum_of_subset <| show { 1, d, m } ⊆ Nat.divisors m from _ );
        · norm_num;
        · norm_num [ Finset.insert_subset_iff ];
          exact ⟨ hm.1.pos.ne', hd.1.symm ▸ dvd_mul_left _ _, hm.1.pos.ne' ⟩;
      rw [ Finset.sum_insert, Finset.sum_insert ] at h_contradiction <;> norm_num at *;
      · grind;
      · nlinarith [ show mersenne ( k + 1 ) > 1 from lt_tsub_iff_left.mpr ( by linarith [ Nat.pow_le_pow_right two_pos ( show k + 1 ≥ 2 by linarith ) ] ) ];
      · rcases m with ( _ | _ | m ) <;> rcases d with ( _ | _ | d ) <;> norm_num at *;
    grind;
  · interval_cases d <;> simp_all +decide [ Nat.Perfect ];
    simp_all +decide [ ArithmeticFunction.sigma_apply, mersenne ];
    simp_all +decide [ Nat.sum_divisors_eq_sum_properDivisors_add_self ];
    exact ⟨ k, by rw [ Nat.prime_def_lt' ] ; exact ⟨ Nat.le_sub_one_of_lt ( by linarith [ Nat.pow_le_pow_right two_pos ( show k + 1 ≥ 2 by linarith ) ] ), fun p hp₁ hp₂ hp₃ => by nlinarith [ Nat.sub_add_cancel ( Nat.one_le_pow ( k + 1 ) 2 zero_lt_two ), show ∑ x ∈ Nat.properDivisors ( 2 ^ ( k + 1 ) - 1 ), x ≥ p from Finset.single_le_sum ( fun x _ => Nat.zero_le x ) ( by aesop ) ] ⟩, rfl ⟩

/-- **Euclid–Euler theorem.** A natural number is an even perfect number iff it is
`2^k * mersenne (k+1)` for some `k` with `mersenne (k+1)` prime. -/
theorem even_perfect_iff_mersenne {n : ℕ} :
    (Even n ∧ Nat.Perfect n) ↔
      ∃ k, (mersenne (k + 1)).Prime ∧ n = 2 ^ k * mersenne (k + 1) := by
  constructor;
  · exact fun hn => by obtain ⟨ k, p, hp₁, hp₂, rfl ⟩ := EuclidEuler.eq_two_pow_mul_prime_mersenne_of_even_perfect hn.2 hn.1; exact ⟨ k, by aesop ⟩ ;
  · rintro ⟨ k, hk₁, rfl ⟩;
    refine' ⟨ _, _ ⟩;
    · cases k <;> simp_all +decide [ Nat.pow_succ', parity_simps ];
    · convert perfect_two_pow_mul_mersenne_of_prime k hk₁ using 1

end EuclidEuler
